import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const q = Number(lines[0]);
const MOD = 1_000_000_007n;
const MAX = 1_000_000;

// 積が 2⁵³ を超えるので、掛け算は BigInt で行い、結果は Number に戻して持つ
const mul = (a: number, b: number): number => Number((BigInt(a) * BigInt(b)) % MOD);
function pow(base: number, exp: number): number {
  let result = 1;
  while (exp > 0) {
    if (exp & 1) result = mul(result, base);
    base = mul(base, base);
    exp >>= 1;
  }
  return result;
}

// fact[i] = i!、inv[i] = (i!) の逆元
const fact = new Array(MAX + 1);
fact[0] = 1;
for (let i = 1; i <= MAX; i++) fact[i] = mul(fact[i - 1], i);
const inv = new Array(MAX + 1);
inv[MAX] = pow(fact[MAX], Number(MOD) - 2); // フェルマーの小定理
for (let i = MAX; i > 0; i--) inv[i - 1] = mul(inv[i], i);

const out: number[] = [];
for (let i = 1; i <= q; i++) {
  const [n, r] = lines[i].split(" ").map(Number);
  out.push(mul(mul(fact[n], inv[r]), inv[n - r]));
}
console.log(out.join("\n"));
